// Mix music, speech and synthesised cues into one track. Gains are dB.
import { execFileSync, spawnSync } from 'node:child_process';
import { rmSync } from 'node:fs';
import { join } from 'node:path';

const TARGET_LUFS = -14;
const PEAK_CEILING = -1.5;

// Original sounds generated by ffmpeg, so a draft has cues with no licensing question.
export const SYNTH = {
  room: (d) => `anoisesrc=c=pink:a=0.5:d=${d}:seed=7,highpass=f=70,lowpass=f=520`,
  air: (d) => `anoisesrc=c=white:a=0.3:d=${d}:seed=9,highpass=f=1200,lowpass=f=6000`,
  whoosh: () => 'anoisesrc=c=pink:a=0.9:d=0.5:seed=3,highpass=f=220,lowpass=f=4200,afade=t=in:d=0.3:curve=exp,afade=t=out:st=0.3:d=0.2',
  tick: () => 'sine=f=1750:d=0.035,afade=t=in:d=0.002,afade=t=out:st=0.002:d=0.033',
  thud: () => 'sine=f=64:d=0.3,afade=t=in:d=0.006,afade=t=out:st=0.015:d=0.28:curve=exp',
  rise: () => 'anoisesrc=c=pink:a=0.7:d=1.2:seed=5,highpass=f=500,lowpass=f=7000,afade=t=in:d=1.15:curve=qsin',
};

export function audioPlan(project, timeline) {
  const tracks = [...(project.audio || []), ...(timeline.audio || [])];
  const cueGain = project.cueGain ?? -7;
  for (const c of timeline.cues || []) {
    if (project.cues === false) break;
    tracks.push({ src: `synth:${c.sound}`, at: c.at, gain: cueGain + (c.gain ?? 0) });
  }
  return tracks;
}

export function mixAudio(root, tracks, duration, out) {
  if (!tracks.length) return false;
  const args = ['-v', 'error', '-y'];
  const chains = [];
  tracks.forEach((t, i) => {
    const synth = String(t.src).startsWith('synth:') ? t.src.slice(6) : null;
    if (synth) {
      if (!SYNTH[synth]) throw new Error(`Unknown synth sound "${synth}". Use: ${Object.keys(SYNTH).join(', ')}`);
      args.push('-f', 'lavfi', '-i', SYNTH[synth](t.duration ?? duration));
    } else {
      args.push('-i', join(root, t.src));
    }
    const f = [];
    if (t.in || t.duration) f.push(`atrim=start=${t.in ?? 0}${t.duration ? `:duration=${t.duration}` : ''}`, 'asetpts=PTS-STARTPTS');
    f.push('aformat=sample_rates=48000:channel_layouts=stereo', `volume=${t.gain ?? 0}dB`);
    if (t.fadeIn) f.push(`afade=t=in:d=${t.fadeIn}`);
    const span = t.duration ?? (synth && ['room', 'air'].includes(synth) ? duration : null);
    if (t.fadeOut && span) f.push(`afade=t=out:st=${Math.max(0, span - t.fadeOut)}:d=${t.fadeOut}`);
    const delay = Math.round((t.at ?? 0) * 1000);
    if (delay) f.push(`adelay=${delay}:all=1`);
    chains.push(`[${i}:a]${f.join(',')}[a${i}]`);
  });
  const labels = tracks.map((_, i) => `[a${i}]`).join('');
  chains.push(`${labels}amix=inputs=${tracks.length}:normalize=0:duration=longest,apad,atrim=0:${duration}[out]`);
  const raw = `${out}.raw.wav`;
  args.push('-filter_complex', chains.join(';'), '-map', '[out]', '-c:a', 'pcm_s24le', '-ar', '48000', raw);
  execFileSync('ffmpeg', args);
  // Measure, then apply one linear gain. Unlike single-pass loudnorm, this cannot overshoot on a sudden cue.
  // Cue-only tracks stay at their set level, so a whoosh is never pushed up to programme loudness.
  const programme = tracks.some((t) => !String(t.src).startsWith('synth:') || ['room', 'air'].includes(String(t.src).slice(6)));
  const { lufs, peak } = measure(raw);
  const toLoudness = programme && Number.isFinite(lufs) ? TARGET_LUFS - lufs : 0;
  const gain = Math.min(toLoudness, PEAK_CEILING - peak);
  const encode = (db) => execFileSync('ffmpeg', ['-v', 'error', '-y', '-i', raw, '-af', `volume=${db.toFixed(2)}dB`, '-c:a', 'aac', '-b:a', '192k', out]);
  encode(gain);
  // AAC can overshoot on transients, so the delivered file is what gets checked.
  const over = measure(out).peak - PEAK_CEILING;
  if (over > 0) encode(gain - over - 0.1);
  rmSync(raw, { force: true });
  return true;
}

function measure(file) {
  const log = spawnSync('ffmpeg', ['-hide_banner', '-nostats', '-i', file, '-af', 'ebur128=peak=true', '-f', 'null', '-'], { encoding: 'utf8', maxBuffer: 1 << 28 }).stderr || '';
  const tail = log.slice(log.lastIndexOf('Summary:'));
  return { lufs: Number(tail.match(/I:\s+(-?[\d.]+) LUFS/)?.[1]), peak: Number(tail.match(/Peak:\s+(-?[\d.]+) dBFS/)?.[1] ?? 0) };
}
